 "Semua Owner dan Admin bisa melihat semua data. Izin di bawah hanya membatasi siapa yang boleh mengubah, menghapus, dan mengelola. Admin + Dev memakai izin kolom Admin 1, ditambah Info Sistem. Hak Owner selalu penuh. Perubahan langsung berlaku.": [
  "Semua Owner dan Admin bisa melihat semua data. Izin di bawah hanya membatasi siapa yang boleh mengubah, menghapus, dan mengelola. Admin + Dev memakai izin kolom Admin 1, ditambah Info Sistem. Hak Owner selalu penuh. Perubahan langsung berlaku.",
  "All Owners and Admins can view all data. The permissions below only limit who can edit, delete, and manage. Admin + Dev uses the Admin 1 column plus System Info. Owner rights are always full. Changes take effect immediately.",
  "Semua Owner dan Admin boleh melihat semua data. Kebenaran di bawah hanya mengehadkan siapa yang boleh mengubah, memadam dan mengurus. Admin + Dev menggunakan kebenaran lajur Admin 1, serta Maklumat Sistem. Hak Owner sentiasa penuh. Perubahan berkuat kuasa serta-merta.",
  "所有 Owner 和 Admin 都可以查看全部数据。下方权限仅限制谁可以修改、删除和管理。Admin + Dev 使用 Admin 1 一列的权限，另加系统信息。Owner 权限始终完整。更改立即生效。",
  "सभी Owner और Admin सारा डेटा देख सकते हैं। नीचे की अनुमतियाँ केवल यह सीमित करती हैं कि कौन बदल, हटा और प्रबंधित कर सकता है। Admin + Dev, Admin 1 कॉलम की अनुमतियों के साथ सिस्टम जानकारी का उपयोग करता है। Owner के अधिकार हमेशा पूर्ण रहते हैं। बदलाव तुरंत लागू होते हैं।",
  "Todos los Owner y Admin pueden ver todos los datos. Los permisos de abajo solo limitan quién puede editar, eliminar y gestionar. Admin + Dev usa los permisos de la columna Admin 1, más Info del sistema. Los derechos de Owner son siempre completos. Los cambios se aplican de inmediato.",
  "يمكن لجميع Owner وAdmin عرض كل البيانات. الصلاحيات أدناه تحدّد فقط من يمكنه التعديل والحذف والإدارة. يستخدم Admin + Dev صلاحيات عمود Admin 1 بالإضافة إلى معلومات النظام. صلاحيات Owner كاملة دائماً. تسري التغييرات فوراً.",
  "Tous les Owner et Admin peuvent voir toutes les données. Les autorisations ci-dessous limitent uniquement qui peut modifier, supprimer et gérer. Admin + Dev utilise les autorisations de la colonne Admin 1, plus les infos système. Les droits Owner sont toujours complets. Les modifications s'appliquent immédiatement.",
  "Todos os Owner e Admin podem ver todos os dados. As permissões abaixo limitam apenas quem pode editar, excluir e gerenciar. Admin + Dev usa as permissões da coluna Admin 1, mais Info do sistema. Os direitos de Owner são sempre totais. As alterações entram em vigor imediatamente.",
  "Все Owner и Admin видят все данные. Разрешения ниже ограничивают только то, кто может изменять, удалять и управлять. Admin + Dev использует разрешения столбца Admin 1 плюс «О системе». Права Owner всегда полные. Изменения вступают в силу сразу.",
  "すべての Owner と Admin は全データを閲覧できます。以下の権限は、変更・削除・管理できる人のみを制限します。Admin + Dev は Admin 1 列の権限に加えてシステム情報を使えます。Owner の権限は常にフルです。変更はすぐに反映されます。"
 ],
