 "Ketuk akun untuk mengubah role, akses Developer, atau menonaktifkannya. Peran Owner bisa diserahkan ke akun lain lewat tombol \"Jadikan Owner\". Selalu ada minimal satu Owner aktif.": [
  "Ketuk akun untuk mengubah role, akses Developer, atau menonaktifkannya. Peran Owner bisa diserahkan ke akun lain lewat tombol \"Jadikan Owner\". Selalu ada minimal satu Owner aktif.",
  "Tap an account to change its role, Developer access, or deactivate it. The Owner role can be handed to another account with the \"Make Owner\" button. There is always at least one active Owner.",
  "Ketik akaun untuk mengubah peranan, akses Developer, atau menyahaktifkannya. Peranan Owner boleh diserahkan kepada akaun lain melalui butang \"Jadikan Owner\". Sentiasa ada sekurang-kurangnya satu Owner aktif.",
  "点按账号可更改其角色、开发者权限或停用账号。可通过“设为 Owner”按钮将 Owner 角色转交给其他账号。始终至少有一位活跃的 Owner。",
  "भूमिका, डेवलपर एक्सेस बदलने या खाता निष्क्रिय करने के लिए खाते पर टैप करें। \"Owner बनाएँ\" बटन से Owner की भूमिका किसी अन्य खाते को सौंपी जा सकती है। हमेशा कम से कम एक सक्रिय Owner रहता है।",
  "Toca una cuenta para cambiar su rol, el acceso de Developer o desactivarla. El rol de Owner se puede ceder a otra cuenta con el botón \"Convertir en Owner\". Siempre hay al menos un Owner activo.",
  "اضغط على حساب لتغيير دوره أو صلاحية المطوّر أو تعطيله. يمكن نقل دور Owner إلى حساب آخر عبر زر \"تعيين كـ Owner\". يوجد دائماً Owner نشط واحد على الأقل.",
  "Touchez un compte pour modifier son rôle, l'accès Developer ou le désactiver. Le rôle Owner peut être transmis à un autre compte avec le bouton \"Nommer Owner\". Il y a toujours au moins un Owner actif.",
  "Toque em uma conta para alterar o papel, o acesso de Developer ou desativá-la. O papel de Owner pode ser transferido a outra conta pelo botão \"Tornar Owner\". Sempre há pelo menos um Owner ativo.",
  "Нажмите на аккаунт, чтобы изменить роль, доступ Developer или отключить его. Роль Owner можно передать другому аккаунту кнопкой \"Сделать Owner\". Всегда есть хотя бы один активный Owner.",
  "アカウントをタップすると、ロールや Developer アクセスの変更、無効化ができます。Owner の役割は「Owner にする」ボタンで別のアカウントに引き継げます。常に 1 人以上の有効な Owner がいます。"
 ],
