 "Tampil sebagai popup dengan tombol X di Dashboard, satu kali saat tiap akun pertama kali membuka Dashboard setelah terbit. Owner dan Admin mana pun boleh membuat.": [
  "Tampil sebagai popup dengan tombol X di Dashboard, satu kali saat tiap akun pertama kali membuka Dashboard setelah terbit. Owner dan Admin mana pun boleh membuat.",
  "Shown as a popup with an X button on the Dashboard, once per account the first time it opens the Dashboard after publishing. Any Owner or Admin can create one.",
  "Dipaparkan sebagai popup dengan butang X di Dashboard, sekali bagi setiap akaun apabila pertama kali membuka Dashboard selepas diterbitkan. Mana-mana Owner dan Admin boleh membuatnya.",
  "以带 X 按钮的弹窗形式显示在 Dashboard 上，发布后每个账号首次打开 Dashboard 时显示一次。任何 Owner 和 Admin 都可以创建。",
  "Dashboard पर X बटन वाले पॉपअप के रूप में दिखता है, प्रकाशन के बाद हर खाते के पहली बार Dashboard खोलने पर एक बार। कोई भी Owner और Admin बना सकता है।",
  "Se muestra como ventana emergente con botón X en el Dashboard, una vez por cuenta la primera vez que abre el Dashboard tras publicarse. Cualquier Owner o Admin puede crearlo.",
  "تظهر كنافذة منبثقة بزر X في Dashboard، مرة واحدة لكل حساب عند فتح Dashboard لأول مرة بعد النشر. يمكن لأي Owner أو Admin إنشاؤها.",
  "Affiché sous forme de popup avec un bouton X sur le Dashboard, une seule fois par compte à sa première ouverture du Dashboard après publication. Tout Owner ou Admin peut en créer.",
  "Exibido como popup com botão X no Dashboard, uma vez por conta na primeira vez que abrir o Dashboard após a publicação. Qualquer Owner ou Admin pode criar.",
  "Показывается как всплывающее окно с кнопкой X на Dashboard один раз для каждого аккаунта при первом открытии Dashboard после публикации. Создавать может любой Owner или Admin.",
  "Dashboard にバツボタン付きのポップアップとして表示され、公開後に各アカウントが初めて Dashboard を開いたときに 1 回だけ表示されます。Owner と Admin なら誰でも作成できます。"
 ],
