 "Menambah Alat Developer (Info Sistem). Cukup aktif atau nonaktif, tanpa masa berlaku.": [
  "Menambah Alat Developer (Info Sistem). Cukup aktif atau nonaktif, tanpa masa berlaku.",
  "Adds Developer Tools (System Info). Just on or off, with no expiry.",
  "Menambah Alat Pembangun (Maklumat Sistem). Hanya hidup atau mati, tanpa tempoh sah.",
  "增加开发者工具（系统信息）。仅需开启或关闭，无有效期。",
  "डेवलपर टूल्स (सिस्टम जानकारी) जोड़ता है। बस चालू या बंद, कोई समय-सीमा नहीं।",
  "Añade Herramientas de desarrollador (Info del sistema). Solo activado o desactivado, sin caducidad.",
  "يضيف أدوات المطوّر (معلومات النظام). تشغيل أو إيقاف فقط، بدون مدة صلاحية.",
  "Ajoute les Outils développeur (Infos système). Simple activation ou désactivation, sans expiration.",
  "Adiciona as Ferramentas de desenvolvedor (Info do sistema). Apenas ligar ou desligar, sem validade.",
  "Добавляет инструменты разработчика («О системе»). Просто вкл. или выкл., без срока действия.",
  "開発者ツール（システム情報）を追加します。オン／オフのみで、有効期限はありません。"
 ],
