 "Cadangan dibuat di Dashboard melalui Pengaturan, lalu Backup Semua Data. Waktunya dicatat secara otomatis di sini.": [
  "Cadangan dibuat di Dashboard melalui Pengaturan, lalu Backup Semua Data. Waktunya dicatat secara otomatis di sini.",
  "Backups are created in the Dashboard via Settings, then Back Up All Data. The time is recorded automatically here.",
  "Sandaran dibuat di Dashboard melalui Tetapan, kemudian Sandar Semua Data. Masanya dicatat secara automatik di sini.",
  "备份在仪表板中通过“设置”→“备份所有数据”创建，时间会自动记录在此处。",
  "बैकअप डैशबोर्ड में सेटिंग्स → सभी डेटा का बैकअप से बनाया जाता है। समय यहाँ अपने-आप दर्ज होता है।",
  "Las copias de seguridad se crean en el Panel desde Ajustes y luego «Copia de seguridad de todos los datos». La hora se registra aquí automáticamente.",
  "تُنشأ النسخ الاحتياطية في لوحة التحكم عبر الإعدادات ثم «نسخ احتياطي لكل البيانات». يُسجَّل الوقت هنا تلقائيًا.",
  "Les sauvegardes se créent dans le tableau de bord via Réglages, puis « Sauvegarder toutes les données ». L'heure est enregistrée ici automatiquement.",
  "Os backups são criados no Painel em Configurações e depois «Backup de todos os dados». O horário é registrado aqui automaticamente.",
  "Резервные копии создаются на панели: «Настройки» → «Резервное копирование всех данных». Время фиксируется здесь автоматически.",
  "バックアップはダッシュボードの「設定」から「全データのバックアップ」で作成します。日時はここに自動で記録されます。"
 ],
