 "Jenis, Nama, dan Total wajib diisi. Dibayar dan Keterangan boleh menyusul lewat Edit. Sisa dihitung otomatis. Data di halaman ini terpisah total dari buku besar, warung, dan kasbon.": [
  "Jenis, Nama, dan Total wajib diisi. Dibayar dan Keterangan boleh menyusul lewat Edit. Sisa dihitung otomatis. Data di halaman ini terpisah total dari buku besar, warung, dan kasbon.",
  "Type, Name, and Total are required. Paid and Remarks can be added later via Edit. Remaining is calculated automatically. Data on this page is completely separate from the main ledger, shop, and cash advance books.",
  "Jenis, Nama dan Jumlah wajib diisi. Dibayar dan Catatan boleh menyusul melalui Sunting. Baki dikira secara automatik. Data di halaman ini sepenuhnya berasingan daripada buku besar, kedai dan kasbon.",
  "类型、名称和合计为必填项。已付和备注可稍后通过“编辑”补充。剩余金额自动计算。此页面的数据与总账、小店和预支账簿完全独立。",
  "प्रकार, नाम और कुल भरना आवश्यक है। भुगतान किया और विवरण बाद में संपादित करें से जोड़े जा सकते हैं। शेष अपने-आप गिना जाता है। इस पेज का डेटा मुख्य बही, दुकान और एडवांस बही से पूरी तरह अलग है।",
  "Tipo, Nombre y Total son obligatorios. Pagado y Observaciones pueden añadirse después con Editar. El Resto se calcula automáticamente. Los datos de esta página están totalmente separados del libro mayor, la tienda y los anticipos.",
  "النوع والاسم والإجمالي حقول مطلوبة. يمكن إضافة المدفوع والملاحظات لاحقًا عبر تعديل. يُحسب المتبقي تلقائيًا. بيانات هذه الصفحة منفصلة تمامًا عن دفتر الأستاذ والمتجر والسلف.",
  "Type, Nom et Total sont obligatoires. Payé et Remarques peuvent être ajoutés plus tard via Modifier. Le Reste est calculé automatiquement. Les données de cette page sont totalement séparées du grand livre, de la boutique et des avances.",
  "Tipo, Nome e Total são obrigatórios. Pago e Observações podem ser adicionados depois por Editar. O Resta é calculado automaticamente. Os dados desta página são totalmente separados do livro-razão, da loja e dos adiantamentos.",
  "Тип, имя и итог обязательны. «Оплачено» и примечание можно добавить позже через «Изменить». Остаток считается автоматически. Данные на этой странице полностью отделены от главной книги, магазина и авансов.",
  "種類・名前・合計は必須です。支払済みと備考は後から「編集」で追加できます。残りは自動計算されます。このページのデータは、総勘定帳・店舗・前借帳とは完全に独立しています。"
 ],
 "Jika dikosongkan, pengumuman terbit saat tombol Terbitkan ditekan. Masa berlaku dihitung sejak waktu terbit.": [
  "Jika dikosongkan, pengumuman terbit saat tombol Terbitkan ditekan. Masa berlaku dihitung sejak waktu terbit.",
  "If left blank, the announcement is published when the Publish button is tapped. The validity period is counted from the publish time.",
  "Jika dikosongkan, pengumuman diterbitkan apabila butang Terbit ditekan. Tempoh sah dikira sejak masa terbit.",
  "留空时，点击“发布”按钮即发布公告。有效期从发布时间起算。",
  "खाली छोड़ने पर, प्रकाशित करें बटन दबाते ही घोषणा प्रकाशित हो जाती है। वैधता अवधि प्रकाशन समय से गिनी जाती है।",
  "Si se deja vacío, el anuncio se publica al pulsar el botón Publicar. La vigencia se cuenta desde la hora de publicación.",
  "إذا تُرك فارغًا، يُنشر الإعلان عند الضغط على زر نشر. تُحتسب مدة الصلاحية من وقت النشر.",
  "Si le champ est vide, l'annonce est publiée dès que vous appuyez sur Publier. La durée de validité est comptée à partir de l'heure de publication.",
  "Se ficar vazio, o anúncio é publicado ao tocar em Publicar. A validade é contada a partir do horário de publicação.",
  "Если оставить пустым, объявление публикуется при нажатии кнопки «Опубликовать». Срок действия отсчитывается от времени публикации.",
  "空欄の場合、「公開」ボタンを押した時点でお知らせが公開されます。有効期間は公開時刻から数えます。"
 ],
