 "Nama Barang dan Jumlah wajib diisi. Keterangan dan Harga boleh menyusul lewat Edit. Data di halaman ini terpisah total dari buku besar.": [
  "Nama Barang dan Jumlah wajib diisi. Keterangan dan Harga boleh menyusul lewat Edit. Data di halaman ini terpisah total dari buku besar.",
  "Item Name and Quantity are required. Remarks and Price can be added later via Edit. Data on this page is completely separate from the main ledger.",
  "Nama Barang dan Kuantiti wajib diisi. Catatan dan Harga boleh menyusul melalui Sunting. Data di halaman ini sepenuhnya berasingan daripada buku besar.",
  "商品名称和数量为必填项。备注和价格可稍后通过“编辑”补充。此页面的数据与总账完全独立。",
  "सामान का नाम और मात्रा भरना आवश्यक है। विवरण और कीमत बाद में संपादित करें से जोड़ी जा सकती है। इस पेज का डेटा मुख्य बही से पूरी तरह अलग है।",
  "Nombre del artículo y Cantidad son obligatorios. Observaciones y Precio pueden añadirse después con Editar. Los datos de esta página están totalmente separados del libro mayor.",
  "اسم الصنف والكمية حقلان مطلوبان. يمكن إضافة الملاحظات والسعر لاحقًا عبر تعديل. بيانات هذه الصفحة منفصلة تمامًا عن دفتر الأستاذ.",
  "Nom de l'article et Quantité sont obligatoires. Remarques et Prix peuvent être ajoutés plus tard via Modifier. Les données de cette page sont totalement séparées du grand livre.",
  "Nome do item e Quantidade são obrigatórios. Observações e Preço podem ser adicionados depois por Editar. Os dados desta página são totalmente separados do livro-razão.",
  "Название товара и количество обязательны. Примечание и цену можно добавить позже через «Изменить». Данные на этой странице полностью отделены от главной книги.",
  "品名と数量は必須です。備考と価格は後から「編集」で追加できます。このページのデータは総勘定帳とは完全に独立しています。"
 ],
 "Nama customer": [
  "Nama customer",
  "Customer name",
  "Nama pelanggan",
  "客户名称",
  "ग्राहक का नाम",
  "Nombre del cliente",
  "اسم العميل",
  "Nom du client",
  "Nome do cliente",
  "Имя клиента",
  "顧客名"
 ],
 "Nama dan Total Tagihan wajib diisi. Dibayar dan Keterangan boleh menyusul lewat Edit. Sisa Tagihan dihitung otomatis. Data di halaman ini terpisah total dari buku besar dan buku warung.": [
  "Nama dan Total Tagihan wajib diisi. Dibayar dan Keterangan boleh menyusul lewat Edit. Sisa Tagihan dihitung otomatis. Data di halaman ini terpisah total dari buku besar dan buku warung.",
  "Name and Total Bill are required. Paid and Remarks can be added later via Edit. Remaining Bill is calculated automatically. Data on this page is completely separate from the main ledger and the shop book.",
  "Nama dan Jumlah Bil wajib diisi. Dibayar dan Catatan boleh menyusul melalui Sunting. Baki Bil dikira secara automatik. Data di halaman ini sepenuhnya berasingan daripada buku besar dan buku kedai.",
  "名称和账单总额为必填项。已付和备注可稍后通过“编辑”补充。剩余账单自动计算。此页面的数据与总账和小店账簿完全独立。",
  "नाम और कुल बिल भरना आवश्यक है। भुगतान किया और विवरण बाद में संपादित करें से जोड़े जा सकते हैं। बकाया बिल अपने-आप गिना जाता है। इस पेज का डेटा मुख्य बही और दुकान बही से पूरी तरह अलग है।",
  "Nombre y Total de factura son obligatorios. Pagado y Observaciones pueden añadirse después con Editar. La Factura pendiente se calcula automáticamente. Los datos de esta página están totalmente separados del libro mayor y del libro de la tienda.",
  "الاسم وإجمالي الفاتورة حقلان مطلوبان. يمكن إضافة المدفوع والملاحظات لاحقًا عبر تعديل. يُحسب المتبقي من الفاتورة تلقائيًا. بيانات هذه الصفحة منفصلة تمامًا عن دفتر الأستاذ ودفتر المتجر.",
  "Nom et Total facturé sont obligatoires. Payé et Remarques peuvent être ajoutés plus tard via Modifier. Le Reste à payer est calculé automatiquement. Les données de cette page sont totalement séparées du grand livre et du registre de la boutique.",
  "Nome e Total da fatura são obrigatórios. Pago e Observações podem ser adicionados depois por Editar. A Fatura restante é calculada automaticamente. Os dados desta página são totalmente separados do livro-razão e do livro da loja.",
  "Имя и сумма счёта обязательны. «Оплачено» и примечание можно добавить позже через «Изменить». Остаток по счёту считается автоматически. Данные на этой странице полностью отделены от главной книги и книги магазина.",
  "名前と請求合計は必須です。支払済みと備考は後から「編集」で追加できます。未払い残高は自動計算されます。このページのデータは総勘定帳・店舗帳とは完全に独立しています。"
 ],
