 "Pengumuman tampil sebagai jendela popup dengan tombol X, hanya di Dashboard. Popup ditampilkan satu kali untuk setiap akun, yaitu saat Dashboard pertama kali dibuka setelah pengumuman terbit. Pembuat pengumuman juga akan melihatnya. Owner dan Admin mana pun dapat membuat pengumuman.": [
  "Pengumuman tampil sebagai jendela popup dengan tombol X, hanya di Dashboard. Popup ditampilkan satu kali untuk setiap akun, yaitu saat Dashboard pertama kali dibuka setelah pengumuman terbit. Pembuat pengumuman juga akan melihatnya. Owner dan Admin mana pun dapat membuat pengumuman.",
  "Announcements appear as a popup window with an X button, only on the Dashboard. The popup is shown once per account, when the Dashboard is first opened after the announcement is published. The author of the announcement will see it too. Any Owner and Admin can create announcements.",
  "Pengumuman dipaparkan sebagai tetingkap pop timbul dengan butang X, hanya di Dashboard. Pop timbul dipaparkan sekali untuk setiap akaun, iaitu apabila Dashboard dibuka buat pertama kali selepas pengumuman diterbitkan. Pembuat pengumuman juga akan melihatnya. Mana-mana Pemilik dan Admin boleh membuat pengumuman.",
  "公告以带 X 按钮的弹窗形式显示，仅在仪表板中出现。每个账号只显示一次，即公告发布后首次打开仪表板时。公告发布者也会看到。任何所有者和管理员都可以创建公告。",
  "घोषणाएँ X बटन वाली पॉपअप विंडो के रूप में दिखती हैं, केवल डैशबोर्ड पर। पॉपअप हर खाते के लिए एक बार दिखता है, यानी घोषणा प्रकाशित होने के बाद डैशबोर्ड पहली बार खोलने पर। घोषणा बनाने वाला भी इसे देखेगा। कोई भी ओनर और एडमिन घोषणा बना सकता है।",
  "Los anuncios aparecen como ventana emergente con botón X, solo en el Panel. La ventana se muestra una vez por cuenta, al abrir el Panel por primera vez tras publicarse el anuncio. Quien crea el anuncio también lo verá. Cualquier Propietario o Admin puede crear anuncios.",
  "تظهر الإعلانات كنافذة منبثقة بزر X، وذلك في لوحة التحكم فقط. تُعرض النافذة مرة واحدة لكل حساب، أي عند فتح لوحة التحكم لأول مرة بعد نشر الإعلان. وسيراها أيضًا من أنشأ الإعلان. يمكن لأي مالك أو مشرف إنشاء إعلان.",
  "Les annonces s'affichent dans une fenêtre contextuelle avec un bouton X, uniquement dans le tableau de bord. La fenêtre s'affiche une fois par compte, à la première ouverture du tableau de bord après la publication de l'annonce. L'auteur de l'annonce la verra aussi. Tout Propriétaire ou Admin peut créer des annonces.",
  "Os anúncios aparecem como uma janela pop-up com botão X, apenas no Painel. O pop-up é exibido uma vez por conta, na primeira vez que o Painel é aberto após a publicação do anúncio. Quem criou o anúncio também o verá. Qualquer Proprietário ou Admin pode criar anúncios.",
  "Объявления отображаются во всплывающем окне с кнопкой X, только на панели. Окно показывается один раз для каждой учётной записи — при первом открытии панели после публикации объявления. Автор объявления тоже его увидит. Создавать объявления может любой владелец и админ.",
  "お知らせは「×」ボタン付きのポップアップとして、ダッシュボードでのみ表示されます。ポップアップは各アカウントにつき1回、お知らせの公開後にダッシュボードを最初に開いたときに表示されます。作成者にも表示されます。オーナーと管理者ならだれでもお知らせを作成できます。"
 ],
