 "Ini rekap gabungan satu pekan dari beberapa note. Untuk mengubah data, buka note aslinya di folder BUKU BESAR.": [
  "Ini rekap gabungan satu pekan dari beberapa note. Untuk mengubah data, buka note aslinya di folder BUKU BESAR.",
  "This is a combined one-week recap from several notes. To change data, open the original note in the LEDGER folder.",
  "Ini rekap gabungan satu minggu daripada beberapa nota. Untuk mengubah data, buka nota asal dalam folder BUKU BESAR.",
  "这是由多条笔记合并而成的一周汇总。如需修改数据，请在“BUKU BESAR”文件夹中打开原笔记。",
  "यह कई नोट्स का एक सप्ताह का संयुक्त सारांश है। डेटा बदलने के लिए BUKU BESAR फ़ोल्डर में मूल नोट खोलें।",
  "Este es un resumen semanal combinado de varias notas. Para cambiar datos, abre la nota original en la carpeta BUKU BESAR.",
  "هذا ملخص أسبوعي مجمّع من عدة ملاحظات. لتغيير البيانات، افتح الملاحظة الأصلية في مجلد BUKU BESAR.",
  "Ceci est un récapitulatif hebdomadaire combiné de plusieurs notes. Pour modifier les données, ouvrez la note d'origine dans le dossier BUKU BESAR.",
  "Este é um resumo semanal combinado de várias notas. Para alterar os dados, abra a nota original na pasta BUKU BESAR.",
  "Это сводка за неделю, объединяющая несколько заметок. Чтобы изменить данные, откройте исходную заметку в папке BUKU BESAR.",
  "これは複数のノートをまとめた1週間分の集計です。データを変更するには、BUKU BESAR フォルダ内の元のノートを開いてください。"
 ],
