 "Nama PJ wajib diisi (2-60 karakter), dan harus sama persis dengan yang nanti ditulis di kolom PJ buku besar.": [
  "Nama PJ wajib diisi (2-60 karakter), dan harus sama persis dengan yang nanti ditulis di kolom PJ buku besar.",
  "The PIC name is required (2-60 characters) and must match exactly what will be written in the PIC column of the ledger.",
  "Nama PJ wajib diisi (2-60 aksara) dan mesti sama persis dengan yang ditulis dalam lajur PJ buku besar.",
  "必须填写负责人姓名（2–60 个字符），且必须与总账“PJ”列中填写的内容完全一致。",
  "PJ का नाम आवश्यक है (2-60 अक्षर) और यह बही के PJ कॉलम में लिखे नाम से बिल्कुल मेल खाना चाहिए।",
  "El nombre del responsable es obligatorio (2-60 caracteres) y debe coincidir exactamente con el que se escriba en la columna PJ del libro mayor.",
  "اسم المسؤول مطلوب (2-60 حرفًا) ويجب أن يطابق تمامًا ما سيُكتب في عمود PJ بدفتر الأستاذ.",
  "Le nom du responsable est obligatoire (2 à 60 caractères) et doit correspondre exactement à celui saisi dans la colonne PJ du grand livre.",
  "O nome do responsável é obrigatório (2-60 caracteres) e deve ser exatamente igual ao escrito na coluna PJ do livro-razão.",
  "Имя ответственного обязательно (2–60 символов) и должно в точности совпадать с тем, что вводится в столбце PJ главной книги.",
  "担当者名は必須です（2〜60文字）。総勘定帳のPJ列に入力する名前と完全に一致させてください。"
 ],
 "Nama customer wajib diisi (2-60 karakter).": [
  "Nama customer wajib diisi (2-60 karakter).",
  "Customer name is required (2-60 characters).",
  "Nama pelanggan wajib diisi (2-60 aksara).",
  "必须填写客户名称（2–60 个字符）。",
  "ग्राहक का नाम आवश्यक है (2-60 अक्षर)।",
  "El nombre del cliente es obligatorio (2-60 caracteres).",
  "اسم العميل مطلوب (2-60 حرفًا).",
  "Le nom du client est obligatoire (2 à 60 caractères).",
  "O nome do cliente é obrigatório (2-60 caracteres).",
  "Имя клиента обязательно (2–60 символов).",
  "顧客名は必須です（2〜60文字）。"
 ],
