 "Rekap gabungan per pekan belum punya link berbagi. Gunakan opsi gambar / PDF, atau bagikan note aslinya.": [
  "Rekap gabungan per pekan belum punya link berbagi. Gunakan opsi gambar / PDF, atau bagikan note aslinya.",
  "The combined weekly recap doesn't have a share link yet. Use the image / PDF option, or share the original note.",
  "Rekap gabungan mingguan belum ada pautan kongsi. Gunakan pilihan imej / PDF, atau kongsi nota asal.",
  "按周合并的汇总暂无分享链接。请使用图片 / PDF 选项，或分享原笔记。",
  "साप्ताहिक संयुक्त सारांश का अभी कोई शेयर लिंक नहीं है। चित्र / PDF विकल्प का उपयोग करें, या मूल नोट साझा करें।",
  "El resumen semanal combinado aún no tiene enlace para compartir. Usa la opción de imagen / PDF o comparte la nota original.",
  "الملخص الأسبوعي المجمّع ليس له رابط مشاركة بعد. استخدم خيار الصورة / PDF أو شارك الملاحظة الأصلية.",
  "Le récapitulatif hebdomadaire combiné n'a pas encore de lien de partage. Utilisez l'option image / PDF ou partagez la note d'origine.",
  "O resumo semanal combinado ainda não tem link de compartilhamento. Use a opção de imagem / PDF ou compartilhe a nota original.",
  "У сводки за неделю пока нет ссылки для общего доступа. Используйте вариант «изображение / PDF» или поделитесь исходной заметкой.",
  "週ごとの合算まとめには共有リンクがまだありません。画像 / PDF のオプションを使うか、元のノートを共有してください。"
 ],
 "Seluruh data yang diinput dari Dashboard Admin disimpan di database Supabase resmi aplikasi ini dan tidak dibagikan ke pihak ketiga mana pun.": [
  "Seluruh data yang diinput dari Dashboard Admin disimpan di database Supabase resmi aplikasi ini dan tidak dibagikan ke pihak ketiga mana pun.",
  "All data entered from the Admin Dashboard is stored in this app's official Supabase database and is not shared with any third party.",
  "Semua data yang dimasukkan daripada Dashboard Admin disimpan dalam pangkalan data Supabase rasmi aplikasi ini dan tidak dikongsi dengan mana-mana pihak ketiga.",
  "从管理员仪表板输入的所有数据都存储在本应用官方的 Supabase 数据库中，不会与任何第三方共享。",
  "एडमिन डैशबोर्ड से दर्ज किया गया सारा डेटा इस ऐप के आधिकारिक Supabase डेटाबेस में संग्रहीत है और किसी तीसरे पक्ष के साथ साझा नहीं किया जाता।",
  "Todos los datos introducidos desde el Panel de administración se guardan en la base de datos oficial de Supabase de esta aplicación y no se comparten con terceros.",
  "تُحفظ جميع البيانات المُدخلة من لوحة تحكم المشرف في قاعدة بيانات Supabase الرسمية لهذا التطبيق ولا تُشارك مع أي طرف ثالث.",
  "Toutes les données saisies depuis le tableau de bord admin sont stockées dans la base de données Supabase officielle de cette application et ne sont partagées avec aucun tiers.",
  "Todos os dados inseridos no Painel do administrador são armazenados no banco de dados oficial Supabase deste aplicativo e não são compartilhados com terceiros.",
  "Все данные, введённые в панели администратора, хранятся в официальной базе данных Supabase этого приложения и не передаются третьим лицам.",
  "管理者ダッシュボードから入力されたすべてのデータは、このアプリ公式のSupabaseデータベースに保存され、第三者と共有されることはありません。"
 ],
