 "Halaman ini khusus untuk admin BM-TECH dalam mengelola data folder, notes, dan transaksi yang akan tampil di Viewer Publik.": [
  "Halaman ini khusus untuk admin BM-TECH dalam mengelola data folder, notes, dan transaksi yang akan tampil di Viewer Publik.",
  "This page is exclusively for BM-TECH admins to manage the folder, notes, and transaction data shown in the Public Viewer.",
  "Halaman ini khusus untuk admin BM-TECH mengurus data folder, nota dan transaksi yang akan dipaparkan di Viewer Awam.",
  "此页面仅供 BM-TECH 管理员管理将显示在公开查看器中的文件夹、笔记和交易数据。",
  "यह पेज केवल BM-TECH एडमिन के लिए है, जो पब्लिक व्यूअर में दिखने वाले फ़ोल्डर, नोट्स और लेन-देन डेटा प्रबंधित करते हैं।",
  "Esta página es exclusiva para administradores de BM-TECH para gestionar las carpetas, notas y transacciones que se muestran en el Visor público.",
  "هذه الصفحة مخصصة لمشرفي BM-TECH لإدارة بيانات المجلدات والملاحظات والمعاملات التي تظهر في العارض العام.",
  "Cette page est réservée aux administrateurs BM-TECH pour gérer les dossiers, notes et transactions affichés dans le visualiseur public.",
  "Esta página é exclusiva para administradores do BM-TECH gerenciarem as pastas, notas e transações exibidas no Visualizador público.",
  "Эта страница предназначена только для администраторов BM-TECH для управления папками, заметками и транзакциями, отображаемыми в публичном просмотрщике.",
  "このページは、公開ビューアに表示されるフォルダ・ノート・取引データを管理するBM-TECH管理者専用です。"
 ],
