 "Kamu sedang offline. Data aman tersimpan di HP ini dan akan terkirim otomatis saat online dan editor dibuka lagi.": [
  "Kamu sedang offline. Data aman tersimpan di HP ini dan akan terkirim otomatis saat online dan editor dibuka lagi.",
  "You're offline. Your data is safely stored on this phone and will be sent automatically when you're online and the editor is opened again.",
  "Anda sedang luar talian. Data disimpan dengan selamat di telefon ini dan akan dihantar secara automatik apabila dalam talian dan editor dibuka semula.",
  "您当前处于离线状态。数据已安全保存在此手机上，联网并再次打开编辑器时会自动发送。",
  "आप ऑफ़लाइन हैं। डेटा इस फ़ोन में सुरक्षित है और ऑनलाइन होने पर एडिटर दोबारा खोलने पर अपने-आप भेज दिया जाएगा।",
  "Estás sin conexión. Tus datos están a salvo en este teléfono y se enviarán automáticamente cuando haya conexión y vuelvas a abrir el editor.",
  "أنت غير متصل بالإنترنت. بياناتك محفوظة بأمان على هذا الهاتف وستُرسل تلقائيًا عند الاتصال وإعادة فتح المحرر.",
  "Vous êtes hors ligne. Vos données sont enregistrées en sécurité sur ce téléphone et seront envoyées automatiquement une fois en ligne et l'éditeur rouvert.",
  "Você está offline. Os dados estão salvos com segurança neste celular e serão enviados automaticamente quando houver conexão e o editor for aberto novamente.",
  "Вы не в сети. Данные надёжно сохранены на этом телефоне и будут отправлены автоматически, когда появится интернет и вы снова откроете редактор.",
  "オフラインです。データはこの端末に安全に保存されており、オンラインになってエディタを再度開くと自動送信されます。"
 ],
