 "Data ini akan hilang selamanya dan TIDAK bisa dipulihkan lagi. Geser potongan gambar ke lubang yang pas untuk melanjutkan.": [
  "Data ini akan hilang selamanya dan TIDAK bisa dipulihkan lagi. Geser potongan gambar ke lubang yang pas untuk melanjutkan.",
  "This data will be lost forever and can NOT be restored. Slide the puzzle piece into the matching gap to continue.",
  "Data ini akan hilang selama-lamanya dan TIDAK boleh dipulihkan lagi. Seret kepingan gambar ke lubang yang sesuai untuk meneruskan.",
  "此数据将永久丢失，且无法恢复。请将拼图块滑到对应缺口以继续。",
  "यह डेटा हमेशा के लिए मिट जाएगा और दोबारा पुनर्स्थापित नहीं किया जा सकेगा। जारी रखने के लिए चित्र के टुकड़े को सही खाली जगह पर खिसकाएँ।",
  "Estos datos se perderán para siempre y NO se podrán restaurar. Desliza la pieza al hueco correspondiente para continuar.",
  "ستُفقد هذه البيانات إلى الأبد ولا يمكن استعادتها. اسحب قطعة الصورة إلى الفراغ المناسب للمتابعة.",
  "Ces données seront perdues définitivement et ne pourront PAS être restaurées. Faites glisser la pièce du puzzle dans l'emplacement correspondant pour continuer.",
  "Estes dados serão perdidos para sempre e NÃO poderão ser restaurados. Deslize a peça do quebra-cabeça até o encaixe correto para continuar.",
  "Эти данные будут безвозвратно удалены, и восстановить их будет НЕЛЬЗЯ. Перетащите фрагмент пазла в нужное место, чтобы продолжить.",
  "このデータは完全に失われ、元に戻せません。続行するには、パズルのピースを対応する穴までスライドしてください。"
 ],
 "Data ini (beserta fotonya) akan hilang selamanya dan TIDAK bisa dipulihkan lagi. Geser potongan gambar ke lubang yang pas untuk melanjutkan.": [
  "Data ini (beserta fotonya) akan hilang selamanya dan TIDAK bisa dipulihkan lagi. Geser potongan gambar ke lubang yang pas untuk melanjutkan.",
  "This data (along with its photos) will be lost forever and can NOT be restored. Slide the puzzle piece into the matching gap to continue.",
  "Data ini (bersama fotonya) akan hilang selama-lamanya dan TIDAK boleh dipulihkan lagi. Seret kepingan gambar ke lubang yang sesuai untuk meneruskan.",
  "此数据（包括其照片）将永久丢失，且无法恢复。请将拼图块滑到对应缺口以继续。",
  "यह डेटा (अपनी फ़ोटो सहित) हमेशा के लिए मिट जाएगा और दोबारा पुनर्स्थापित नहीं किया जा सकेगा। जारी रखने के लिए चित्र के टुकड़े को सही खाली जगह पर खिसकाएँ।",
  "Estos datos (junto con sus fotos) se perderán para siempre y NO se podrán restaurar. Desliza la pieza al hueco correspondiente para continuar.",
  "ستُفقد هذه البيانات (مع صورها) إلى الأبد ولا يمكن استعادتها. اسحب قطعة الصورة إلى الفراغ المناسب للمتابعة.",
  "Ces données (avec leurs photos) seront perdues définitivement et ne pourront PAS être restaurées. Faites glisser la pièce du puzzle dans l'emplacement correspondant pour continuer.",
  "Estes dados (junto com as fotos) serão perdidos para sempre e NÃO poderão ser restaurados. Deslize a peça do quebra-cabeça até o encaixe correto para continuar.",
  "Эти данные (вместе с фото) будут безвозвратно удалены, и восстановить их будет НЕЛЬЗЯ. Перетащите фрагмент пазла в нужное место, чтобы продолжить.",
  "このデータ（写真を含む）は完全に失われ、元に戻せません。続行するには、パズルのピースを対応する穴までスライドしてください。"
 ],
