 "Tulis nomor HP customer (08... atau +62...) di kolom Keterangan Buku Besar, nomornya akan muncul di sini.": [
  "Tulis nomor HP customer (08... atau +62...) di kolom Keterangan Buku Besar, nomornya akan muncul di sini.",
  "Write the customer's phone number (08... or +62...) in the Remarks column of the Ledger and the number will appear here.",
  "Tulis nombor telefon pelanggan (08... atau +62...) dalam lajur Catatan Buku Besar, nombor itu akan muncul di sini.",
  "在总账的“备注”列中填写客户手机号（08... 或 +62...），号码就会显示在这里。",
  "ग्राहक का फ़ोन नंबर (08... या +62...) मुख्य बही के विवरण कॉलम में लिखें, नंबर यहाँ दिखाई देगा।",
  "Escribe el teléfono del cliente (08... o +62...) en la columna Observaciones del Libro mayor y el número aparecerá aquí.",
  "اكتب رقم هاتف العميل (08... أو +62...) في عمود الملاحظات بدفتر الأستاذ وسيظهر الرقم هنا.",
  "Saisissez le numéro de téléphone du client (08... ou +62...) dans la colonne Remarques du Grand livre et il apparaîtra ici.",
  "Escreva o telefone do cliente (08... ou +62...) na coluna Observações do Livro-razão e o número aparecerá aqui.",
  "Укажите номер телефона клиента (08... или +62...) в столбце «Примечание» главной книги, и он появится здесь.",
  "顧客の電話番号（08... または +62...）を総勘定帳の備考欄に書くと、ここに表示されます。"
 ],
