  "ऐसा डेटा जिसका कोई कॉलम अभी खाली है: ग्राहक, निकला सामान, छोड़ा गया सामान, विवरण या कीमत।",
  "Datos con alguna columna todavía vacía: Cliente, Artículos salidos, Artículos dejados, Observaciones o Precio.",
  "بيانات أحد أعمدتها ما زال فارغًا: العميل أو الأصناف الخارجة أو الأغراض المتروكة أو ملاحظات أو السعر.",
  "Données dont l'une des colonnes est encore vide : Client, Articles sortis, Articles laissés, Remarques ou Prix.",
  "Dados com alguma coluna ainda vazia: Cliente, Itens saídos, Itens deixados, Observações ou Preço.",
