 "Tiap baris menampilkan nama customer (atau “(tanpa customer)”), PJ, barang, keterangan, lalu tanggal dan jam.": [
  "Tiap baris menampilkan nama customer (atau “(tanpa customer)”), PJ, barang, keterangan, lalu tanggal dan jam.",
  "Each row shows the customer name (or “(no customer)”), PIC, items, remarks, then the date and time.",
  "Setiap baris memaparkan nama pelanggan (atau “(tanpa pelanggan)”), PJ, barang, keterangan, kemudian tarikh dan masa.",
  "每行显示客户名称(或“(无客户)”)、负责人、物品、备注,以及日期和时间。",
  "हर पंक्ति में ग्राहक का नाम (या “(बिना ग्राहक)”), जिम्मेदार व्यक्ति, सामान, विवरण, फिर तारीख और समय दिखता है।",
  "Cada fila muestra el nombre del cliente (o “(sin cliente)”), responsable, artículos, observaciones y luego fecha y hora.",
  "يعرض كل صف اسم العميل (أو «(بدون عميل)») والمسؤول والأصناف والملاحظات ثم التاريخ والوقت.",
  "Chaque ligne affiche le nom du client (ou « (sans client) »), le responsable, les articles, les remarques, puis la date et l'heure.",
  "Cada linha mostra o nome do cliente (ou “(sem cliente)”), responsável, itens, observações e depois data e hora.",
  "В каждой строке указаны имя клиента (или «(без клиента)»), ответственный, товары, примечание, затем дата и время.",
  "各行には顧客名(または「(顧客なし)」)、担当者、品目、備考、日付と時刻が表示されます。"
 ],
