 "Tulis nama dengan ejaan yang sama setiap kali. Huruf besar/kecil dan spasi ganda tidak berpengaruh. Nama ini dipakai untuk menemukan titipan lama.": [
  "Tulis nama dengan ejaan yang sama setiap kali. Huruf besar/kecil dan spasi ganda tidak berpengaruh. Nama ini dipakai untuk menemukan titipan lama.",
  "Write the name with the same spelling every time. Upper/lower case and double spaces make no difference. This name is used to find earlier deposited items.",
  "Tulis nama dengan ejaan yang sama setiap kali. Huruf besar/kecil dan ruang berganda tidak menjadi masalah. Nama ini digunakan untuk mencari barang titipan lama.",
  "每次都用相同的拼写填写姓名。大小写和多余空格不影响结果。该名称用于查找之前的寄存物品。",
  "हर बार नाम की वर्तनी एक जैसी लिखें। बड़े/छोटे अक्षर और दोहरी जगह का कोई असर नहीं पड़ता। इस नाम से पुराने जमा सामान ढूँढे जाते हैं।",
  "Escribe el nombre con la misma ortografía cada vez. Mayúsculas/minúsculas y espacios dobles no importan. Este nombre sirve para encontrar depósitos anteriores.",
  "اكتب الاسم بنفس الإملاء في كل مرة. لا يؤثر اختلاف الحروف الكبيرة والصغيرة أو المسافات المزدوجة. يُستخدم هذا الاسم للعثور على الأغراض المودعة سابقًا.",
  "Écrivez le nom avec la même orthographe à chaque fois. Majuscules/minuscules et doubles espaces n'ont pas d'effet. Ce nom sert à retrouver les anciens dépôts.",
  "Escreva o nome com a mesma grafia sempre. Maiúsculas/minúsculas e espaços duplos não interferem. Esse nome é usado para encontrar itens deixados anteriormente.",
  "Пишите имя одинаково каждый раз. Регистр и двойные пробелы не влияют. По этому имени находятся прежние оставленные вещи.",
  "毎回同じ綴りで名前を入力してください。大文字・小文字や連続スペースは影響しません。この名前で過去の預かり品を検索します。"
 ],
