  "Angka (titik ribuan muncul sendiri) atau tulisan bebas seperti ✓. Boleh dikosongkan dan diisi belakangan.",
  "A number (the thousands separator appears by itself) or free text such as ✓. May be left empty and filled in later.",
  "Angka (titik ribuan muncul sendiri) atau tulisan bebas seperti ✓. Boleh dikosongkan dan diisi kemudian.",
  "数字(千位分隔点自动出现)或自由文字,如 ✓。可留空,稍后再填。",
  "संख्या (हज़ार का बिंदु अपने आप आता है) या ✓ जैसा खुला पाठ। खाली छोड़कर बाद में भर सकते हैं।",
  "Un número (el separador de miles aparece solo) o texto libre como ✓. Se puede dejar vacío y rellenar después.",
  "رقم (تظهر فاصلة الآلاف تلقائيًا) أو نص حر مثل ✓. يمكن تركه فارغًا وملؤه لاحقًا.",
  "Un nombre (le séparateur de milliers apparaît seul) ou du texte libre comme ✓. Peut rester vide et être rempli plus tard.",
  "Um número (o separador de milhar aparece sozinho) ou texto livre como ✓. Pode ficar vazio e ser preenchido depois.",
  "Число (разделитель тысяч появляется сам) или произвольный текст, например ✓. Можно оставить пустым и заполнить позже.",
  "数字(桁区切りは自動で入ります)または ✓ などの自由な文字。空欄にして後から入力しても構いません。"
