  "आज जिन वस्तुओं पर बात हो रही है उन पर टिक करें। अगर जमा डेटा सिर्फ़ एक है, तो उसका सारा सामान तुरंत टिक हो जाता है।",
  "Marca los artículos que se tratan hoy. Si solo hay un registro de depósito, todos sus artículos quedan marcados de inmediato.",
  "ضع علامة على الأصناف التي تُعالَج اليوم. إذا وُجد سجل إيداع واحد فقط، تُحدَّد جميع أصنافه فورًا.",
  "Cochez les articles traités aujourd'hui. S'il n'y a qu'un seul dépôt, tous ses articles sont cochés d'office.",
  "Marque os itens tratados hoje. Se houver apenas um registro de item deixado, todos os seus itens ficam marcados na hora.",
  "Отметьте товары, которые обрабатываются сегодня. Если есть только одна запись об оставленных вещах, все её товары отмечаются сразу.",
