  "Nama barang yang sudah tercatat tidak perlu diketik di Barang dan Jumlah. Kalau terlanjur diketik, otomatis dibuang saat disimpan.",
  "Items that are already recorded don't need to be typed in Items and Quantity. If typed anyway, they are removed automatically on saving.",
  "Nama barang yang sudah tercatat tidak perlu ditaip di Barang dan Kuantiti. Jika sudah ditaip, ia dibuang secara automatik semasa disimpan.",
  "已记录的物品名称无需再填在“物品与数量”中。如果已经填了,保存时会自动删除。",
