  "Los nombres de artículos ya registrados no hace falta escribirlos en Artículos y cantidad. Si se escriben, se eliminan automáticamente al guardar.",
  "لا حاجة لكتابة أسماء الأصناف المسجلة سابقًا في الأغراض والكمية. وإذا كُتبت فستُحذف تلقائيًا عند الحفظ.",
