 "Berlaku juga untuk titipan di catatan lain di folder yang sama.": [
  "Berlaku juga untuk titipan di catatan lain di folder yang sama.",
  "Also applies to deposits in other records in the same folder.",
  "Terpakai juga untuk titipan dalam catatan lain dalam folder yang sama.",
  "同一文件夹中其他记录的寄存物品同样适用。",
  "यह उसी फ़ोल्डर के अन्य रिकॉर्ड के जमा सामान पर भी लागू होता है।",
  "También se aplica a los depósitos de otros registros de la misma carpeta.",
  "ينطبق أيضًا على الإيداعات في السجلات الأخرى داخل المجلد نفسه.",
  "S'applique aussi aux dépôts des autres registres du même dossier.",
  "Também vale para itens deixados em outros registros da mesma pasta.",
  "Действует и для оставленных вещей в других записях той же папки.",
  "同じフォルダ内の他の記録にある預かり品にも適用されます。"
 ],
