 "Ubah kolom yang perlu: PJ, Customer, Barang dan Jumlah, Barang Keluar, Barang Ditinggal, Keterangan, Harga, Metode Bayar, dan Bukti (tambah atau hapus gambar).": [
  "Ubah kolom yang perlu: PJ, Customer, Barang dan Jumlah, Barang Keluar, Barang Ditinggal, Keterangan, Harga, Metode Bayar, dan Bukti (tambah atau hapus gambar).",
  "Change whichever columns you need: PIC, Customer, Items and Quantity, Items Out, Items Left, Remarks, Price, Payment Method, and Proof (add or remove images).",
  "Ubah lajur yang perlu: PJ, Pelanggan, Barang dan Kuantiti, Barang Keluar, Barang Ditinggalkan, Keterangan, Harga, Kaedah Bayaran, dan Bukti (tambah atau buang gambar).",
  "修改需要的栏位:负责人、客户、物品与数量、出库商品、留下的物品、备注、价格、支付方式和凭证(添加或删除图片)。",
  "ज़रूरी कॉलम बदलें: जिम्मेदार व्यक्ति, ग्राहक, सामान और मात्रा, निकला सामान, छोड़ा गया सामान, विवरण, कीमत, भुगतान का तरीका और प्रमाण (तस्वीर जोड़ें या हटाएँ)।",
  "Cambia las columnas que necesites: responsable, Cliente, Artículos y cantidad, Artículos salidos, Artículos dejados, Observaciones, Precio, Método de pago y Comprobante (añadir o quitar imágenes).",
  "غيّر الأعمدة اللازمة: المسؤول، العميل، الأغراض والكمية، الأصناف الخارجة، الأغراض المتروكة، ملاحظات، السعر، طريقة الدفع، والإثبات (إضافة الصور أو حذفها).",
  "Modifiez les colonnes voulues : responsable, Client, Articles et quantité, Articles sortis, Articles laissés, Remarques, Prix, Mode de paiement et Justificatif (ajouter ou supprimer des images).",
  "Altere as colunas necessárias: responsável, Cliente, Itens e quantidade, Itens saídos, Itens deixados, Observações, Preço, Forma de pagamento e Comprovante (adicionar ou remover imagens).",
  "Измените нужные столбцы: ответственный, Клиент, Товары и количество, Расход товара, Оставленные товары, Примечание, Цена, Способ оплаты и Подтверждение (добавить или удалить изображения).",
  "必要な列を変更します:担当者、顧客、品目と数量、出庫品目、預かり品目、備考、価格、支払い方法、証拠(画像の追加・削除)。"
 ],
 "Nomor, Tanggal, dan Waktu tidak bisa diubah. Di mode Edit kadang muncul pilihan tambahan:": [
  "Nomor, Tanggal, dan Waktu tidak bisa diubah. Di mode Edit kadang muncul pilihan tambahan:",
  "Number, Date, and Time cannot be changed. In Edit mode extra options sometimes appear:",
  "Nombor, Tarikh dan Masa tidak boleh diubah. Dalam mod Edit kadangkala muncul pilihan tambahan:",
  "编号、日期和时间不能修改。编辑模式下有时会出现额外选项:",
  "नंबर, तारीख और समय बदले नहीं जा सकते। संपादन मोड में कभी-कभी अतिरिक्त विकल्प दिखते हैं:",
  "Número, Fecha y Hora no se pueden cambiar. En el modo de edición a veces aparecen opciones adicionales:",
  "لا يمكن تغيير الرقم والتاريخ والوقت. في وضع التعديل تظهر أحيانًا خيارات إضافية:",
  "Numéro, Date et Heure ne sont pas modifiables. En mode modification, des options supplémentaires apparaissent parfois :",
  "Número, Data e Hora não podem ser alterados. No modo de edição, às vezes aparecem opções adicionais:",
  "Номер, дату и время изменить нельзя. В режиме редактирования иногда появляются дополнительные варианты:",
  "番号、日付、時刻は変更できません。編集モードでは追加の選択肢が表示されることがあります:"
 ],
