 "Muncul di Detail Data kalau data itu punya barang yang dilacak. Tiap barang satu baris, berisi dua label: posisi barang dan status bayarnya.": [
  "Muncul di Detail Data kalau data itu punya barang yang dilacak. Tiap barang satu baris, berisi dua label: posisi barang dan status bayarnya.",
  "Appears in Data Details when that data has tracked items. Each item gets one row with two labels: where the item is and its payment status.",
  "Muncul dalam Butiran Data jika data itu mempunyai barang yang dijejaki. Setiap barang satu baris, mengandungi dua label: kedudukan barang dan status bayarannya.",
  "当该数据含有被追踪的物品时,会显示在数据详情中。每件物品一行,带有两个标签:物品所在位置和付款状态。",
  "जब उस डेटा में ट्रैक किया जा रहा सामान हो तो डेटा विवरण में दिखता है। हर वस्तु की एक पंक्ति होती है जिसमें दो लेबल होते हैं: सामान की स्थिति और भुगतान स्थिति।",
  "Aparece en el detalle del dato si tiene artículos con seguimiento. Cada artículo ocupa una fila con dos etiquetas: su ubicación y su estado de pago.",
  "يظهر في تفاصيل البيانات إذا كانت تحتوي على أصناف قيد التتبع. لكل صنف صف واحد بتسميتين: موضع الصنف وحالة دفعه.",
  "Apparaît dans le détail de la donnée si elle contient des articles suivis. Chaque article occupe une ligne avec deux étiquettes : sa position et son statut de paiement.",
  "Aparece nos detalhes do dado quando ele tem itens rastreados. Cada item ocupa uma linha com dois rótulos: a posição do item e o status de pagamento.",
  "Отображается в деталях данных, если в них есть отслеживаемые товары. На каждый товар одна строка с двумя метками: где находится товар и статус оплаты.",
  "追跡対象の品目があるデータでは、データ詳細に表示されます。品目ごとに1行で、品目の所在と支払い状況の2つのラベルが付きます。"
 ],
