 "Setiap perubahan (menambah, mengedit, menghapus, mengganti judul) dikirim otomatis sekitar 1 detik setelahnya. Di layar muncul keterangan status:": [
  "Setiap perubahan (menambah, mengedit, menghapus, mengganti judul) dikirim otomatis sekitar 1 detik setelahnya. Di layar muncul keterangan status:",
  "Every change (adding, editing, deleting, renaming the title) is sent automatically about 1 second later. A status message appears on screen:",
  "Setiap perubahan (menambah, mengedit, memadam, menukar tajuk) dihantar secara automatik kira-kira 1 saat selepasnya. Keterangan status muncul pada skrin:",
  "每次更改(添加、编辑、删除、更改标题)约 1 秒后自动发送。屏幕上会显示状态提示:",
  "हर बदलाव (जोड़ना, संपादन, हटाना, शीर्षक बदलना) लगभग 1 सेकंड बाद अपने आप भेज दिया जाता है। स्क्रीन पर स्थिति संदेश दिखता है:",
  "Cada cambio (añadir, editar, eliminar, cambiar el título) se envía automáticamente aproximadamente 1 segundo después. En pantalla aparece un mensaje de estado:",
  "يُرسل كل تغيير (إضافة أو تعديل أو حذف أو تغيير العنوان) تلقائيًا بعد نحو ثانية واحدة. تظهر رسالة حالة على الشاشة:",
  "Chaque modification (ajout, modification, suppression, changement de titre) est envoyée automatiquement environ 1 seconde plus tard. Un message d'état s'affiche à l'écran :",
  "Cada alteração (adicionar, editar, excluir, trocar o título) é enviada automaticamente cerca de 1 segundo depois. Uma mensagem de status aparece na tela:",
  "Каждое изменение (добавление, редактирование, удаление, смена заголовка) отправляется автоматически примерно через 1 секунду. На экране появляется статус:",
  "すべての変更(追加・編集・削除・タイトル変更)は約1秒後に自動送信されます。画面にステータスが表示されます:"
 ],
