 "Pengiriman gagal. Editor mengulang sendiri dengan jeda makin lama (maksimal 30 detik).": [
  "Pengiriman gagal. Editor mengulang sendiri dengan jeda makin lama (maksimal 30 detik).",
  "Sending failed. The editor retries by itself with longer and longer pauses (up to 30 seconds).",
  "Penghantaran gagal. Editor mengulang sendiri dengan selang yang makin lama (maksimum 30 saat).",
  "发送失败。编辑器会自动重试,间隔越来越长(最长 30 秒)。",
  "भेजना विफल रहा। एडिटर खुद दोबारा कोशिश करता है, हर बार अंतराल बढ़ता जाता है (अधिकतम 30 सेकंड)।",
  "Falló el envío. El editor reintenta solo con pausas cada vez más largas (máximo 30 segundos).",
  "فشل الإرسال. يعيد المحرر المحاولة تلقائيًا بفواصل أطول فأطول (حتى 30 ثانية).",
  "L'envoi a échoué. L'éditeur réessaie seul avec des pauses de plus en plus longues (30 secondes maximum).",
  "O envio falhou. O editor tenta de novo sozinho com pausas cada vez maiores (máximo de 30 segundos).",
  "Отправка не удалась. Редактор повторяет попытки сам, с всё большими паузами (максимум 30 секунд).",
  "送信に失敗しました。エディターが間隔を延ばしながら自動で再試行します(最大30秒)。"
 ],
 "Data catatan lama (tabel bebas) diimpor otomatis ke format baru, dan data aslinya tetap diarsipkan.": [
  "Data catatan lama (tabel bebas) diimpor otomatis ke format baru, dan data aslinya tetap diarsipkan.",
  "Old record data (free-form table) is imported automatically into the new format, and the original data is still archived.",
  "Data catatan lama (jadual bebas) diimport secara automatik ke format baharu, dan data asalnya tetap diarkibkan.",
  "旧记录数据(自由表格)会自动导入新格式,原始数据仍会存档。",
  "पुराने रिकॉर्ड का डेटा (फ़्री-फ़ॉर्म तालिका) अपने आप नए प्रारूप में आयात होता है, और मूल डेटा संग्रहित रहता है।",
  "Los datos de registros antiguos (tabla libre) se importan automáticamente al nuevo formato y los datos originales siguen archivados.",
  "تُستورد بيانات السجلات القديمة (الجدول الحر) تلقائيًا إلى الصيغة الجديدة وتبقى البيانات الأصلية مؤرشفة.",
  "Les données des anciens registres (tableau libre) sont importées automatiquement au nouveau format, et les données d'origine restent archivées.",
  "Os dados de registros antigos (tabela livre) são importados automaticamente para o novo formato, e os dados originais continuam arquivados.",
  "Данные старых записей (свободная таблица) автоматически импортируются в новый формат, а исходные данные остаются в архиве.",
  "旧記録のデータ(自由形式の表)は自動的に新しい形式へ取り込まれ、元のデータもアーカイブとして保持されます。"
 ],
